#!/usr/bin/env node
// Bundle the guest (inspector) preload into ONE file so it can run with
// `sandbox: true`.
//
// A sandboxed preload cannot require() sibling files from disk — only a handful
// of Electron modules — which is why guests currently run with sandbox:false.
// This script concatenates every CommonJS module reachable from the inspector entry
// (src/webview/ plus the src/shared/ modules it requires) into
// src/webview/dist/guest-preload.bundle.js behind a tiny module registry:
//
//   * relative require()s resolve inside the bundle; everything else
//     (i.e. require('electron')) falls through to the preload's own require;
//   * output is deterministic (sorted ids, LF line endings, no timestamps) and
//     carries a content hash, so `--check` can tell when it is stale;
//   * dependency-free on purpose, like scripts/check.js.
//
//   node scripts/bundle-guest.js          write the bundle
//   node scripts/bundle-guest.js --check  exit 1 if missing or stale
//
// The bundle is opt-in at runtime (BRAIWSER_SANDBOX_GUEST=1). The unbundled
// preload stays the default until the sandboxed guest is confirmed natively.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.join(__dirname, '..');
const DEFAULT_SRC_ROOT = path.join(ROOT, 'src');
const DEFAULT_OUT = path.join(DEFAULT_SRC_ROOT, 'webview', 'dist', 'guest-preload.bundle.js');
// Module ids are paths relative to src/ (no .js), so '../shared/x' required from
// src/webview resolves to 'shared/x' inside the bundle.
const DEFAULT_ENTRY = 'webview/inspector';

function toLf(text) { return text.replace(/\r\n?/g, '\n'); }

const REQUIRE_RE = /\brequire\(\s*(['"])(\.{1,2}\/[^'"]*)\1\s*\)/g;

function resolveFile(root, fromId, request) {
  const parts = fromId.split('/'); parts.pop();
  for (const seg of request.split('/')) {
    if (seg === '.' || seg === '') continue;
    if (seg === '..') parts.pop(); else parts.push(seg);
  }
  const base = parts.join('/').replace(/\.js$/, '');
  for (const cand of [base + '.js', base + '/index.js']) {
    const full = path.join(root, ...cand.split('/'));
    if (fs.existsSync(full) && fs.statSync(full).isFile()) return { id: cand.replace(/\.js$/, ''), file: full };
  }
  return null;
}

// Every module REACHABLE from the entry through relative require()s (webview and
// shared code alike), sorted by id. Unresolvable relative requires are left out on
// purpose: guest code wraps its optional ones in try/catch and the bundle's loader
// throws at runtime exactly like Node would.
function collectModules(root, entry) {
  const entryId = entry || DEFAULT_ENTRY;
  const entryFile = path.join(root, ...entryId.split('/')) + '.js';
  if (!fs.existsSync(entryFile)) throw new Error(`bundle entry not found: ${entryFile}`);
  const seen = new Map();
  const queue = [{ id: entryId, file: entryFile }];
  while (queue.length) {
    const mod = queue.pop();
    if (seen.has(mod.id)) continue;
    const source = fs.readFileSync(mod.file, 'utf8');
    seen.set(mod.id, { id: mod.id, file: mod.file, source });
    for (const m of source.matchAll(REQUIRE_RE)) {
      const dep = resolveFile(root, mod.id, m[2]);
      if (dep && !seen.has(dep.id)) queue.push(dep);
    }
  }
  return Array.from(seen.values()).sort((x, y) => (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
}

// modules: [{ id, source }]. Pure — used directly by tests.
function renderBundle(modules, entry) {
  const sorted = modules.slice().sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  if (!sorted.some((m) => m.id === entry)) throw new Error(`bundle entry "${entry}" not found among modules`);
  const hash = crypto.createHash('sha256');
  for (const m of sorted) hash.update(m.id + '\0' + toLf(m.source) + '\0');
  hash.update('entry:' + entry);
  const digest = hash.digest('hex').slice(0, 16);

  const defs = sorted.map((m) => {
    const body = toLf(m.source);
    return `${JSON.stringify(m.id)}: function (module, exports, require) {\n${body}${body.endsWith('\n') ? '' : '\n'}}`;
  }).join(',\n');

  return [
    '// Braiwser guest preload bundle — GENERATED by scripts/bundle-guest.js. Do not edit.',
    `// bundle-hash: ${digest}`,
    '(function () {',
    "  'use strict';",
    '  var __nodeRequire = require;',
    '  var __defs = {',
    defs,
    '  };',
    '  var __cache = {};',
    '  function __join(from, request) {',
    "    var parts = from.split('/'); parts.pop();",
    "    request.split('/').forEach(function (seg) {",
    "      if (seg === '.' || seg === '') return;",
    "      if (seg === '..') parts.pop(); else parts.push(seg);",
    '    });',
    "    return parts.join('/').replace(/\\.js$/, '');",
    '  }',
    '  function __makeRequire(from) {',
    '    return function (request) {',
    "      if (request.charAt(0) !== '.') return __nodeRequire(request);",
    '      return __load(__join(from, request));',
    '    };',
    '  }',
    '  function __load(id) {',
    '    if (Object.prototype.hasOwnProperty.call(__cache, id)) return __cache[id].exports;',
    "    if (!Object.prototype.hasOwnProperty.call(__defs, id)) throw new Error('Cannot find module ' + id + ' in guest bundle');",
    '    var module = { exports: {} };',
    '    __cache[id] = module;',
    '    __defs[id].call(module.exports, module, module.exports, __makeRequire(id));',
    '    return module.exports;',
    '  }',
    `  __load(${JSON.stringify(entry)});`,
    '})();',
    '',
  ].join('\n');
}

function buildBundle(options) {
  const o = options || {};
  const entry = o.entry || DEFAULT_ENTRY;
  const modules = collectModules(o.root || DEFAULT_SRC_ROOT, entry).map((m) => ({ id: m.id, source: m.source }));
  return renderBundle(modules, entry);
}

function writeBundle(options) {
  const o = options || {};
  const out = o.out || DEFAULT_OUT;
  const text = buildBundle(o);
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, text, 'utf8');
  return { out, bytes: Buffer.byteLength(text), hash: /bundle-hash: (\w+)/.exec(text)[1] };
}

// 'fresh' | 'stale' | 'missing'
function bundleStatus(options) {
  const o = options || {};
  const out = o.out || DEFAULT_OUT;
  if (!fs.existsSync(out)) return 'missing';
  return toLf(fs.readFileSync(out, 'utf8')) === buildBundle(o) ? 'fresh' : 'stale';
}

module.exports = { collectModules, renderBundle, buildBundle, writeBundle, bundleStatus, DEFAULT_OUT, DEFAULT_ENTRY };

if (require.main === module) {
  if (process.argv.includes('--check')) {
    const status = bundleStatus();
    if (status !== 'fresh') {
      console.error(`guest bundle is ${status}; run: npm run build:guest`);
      process.exit(1);
    }
    console.log('guest bundle is up to date');
  } else {
    const r = writeBundle();
    console.log(`guest bundle written: ${path.relative(ROOT, r.out)} (${r.bytes} bytes, hash ${r.hash})`);
  }
}
